export class ConversateEndpoint extends ApiEndpoint {
    public path = "/conversate";

    public async post(
        request: IApiRequest,
        endpoint: IApiEndpointInfo,
        read: IRead,
        modify: IModify,
        http: IHttp,
        persis: IPersistence
    ): Promise<IApiResponse> {
        try {
            if(!request.user){
                return {
                    status: 500,
                    headers: {
                        "Content-Type": "application/json",
                        "Content-Security-Policy":
                        "default-src 'self' http: https: data: blob: 'unsafe-inline' 'unsafe-eval'",
                    },
                    content: "No user"
                };
            }
            // Replace with the actual path to your index.mjs file
            const conversationId: string = request.content.conversationId
            const message: string = request.content.message;
            const messageId = request.content.messageId;

            let finalOutput: IMessageLLM

            await checkOrCreateUser(read, persis, request.user.id)
            await getOrCreateConversation(read, persis, conversationId, request.user.id)
            const conversationData = await getConversationWithID(read, conversationId)

            let oldMsgData : IMessageLLM[] = [
                ...conversationData.messages,
                {
                    role: "user",
                    content: message
                }
            ]

            const [currentReply, history] = await conversateWithLLM(http, oldMsgData, messageId, read)

            console.log(currentReply);
            console.log(history);

            if(currentReply.includes("%ended%")){
                const newMsgData = [
                    {
                        role: "user",
                        content: message
                    },
                    {
                        role: "assistant",
                        content: history
                    }
                ]

                await addNewMessageToConversation(read, persis, request.user.id, conversationId, newMsgData)
            }

            return {
                status: 200,
                headers: {
                    "Content-Type": "application/json",
                    "Content-Security-Policy":
                    "default-src 'self' http: https: data: blob: 'unsafe-inline' 'unsafe-eval'",
                },
                content: {
                    sentBy: "assistant",
                    message: currentReply,
                    conversationId: conversationId,
                    fromMsg : message
                },
            }
        } catch (error) {
            return {
                status: 500,
                content: `Error reading file: ${error.message}`,
            };
        }
    }
}

export class FetchAllConversations extends ApiEndpoint {
    public path = "all-conversations";

    public async get(
        request: IApiRequest,
        endpoint: IApiEndpointInfo,
        read: IRead,
        modify: IModify,
        http: IHttp,
        persis: IPersistence
    ): Promise<IApiResponse> {

        if(!request.user){
            return {
                status: 500,
                headers: {
                    "Content-Type": "application/json",
                    "Content-Security-Policy":
                    "default-src 'self' http: https: data: blob: 'unsafe-inline' 'unsafe-eval'",
                },
                content: "No user"
            };
        }

        const conversationIDs = await getAllConversationsIDS(read, persis, request.user.id);

        return {
            status: 200,
            headers: {
                "Content-Type": "application/json",
                "Content-Security-Policy":
                "default-src 'self' http: https: data: blob: 'unsafe-inline' 'unsafe-eval'",
            },
            content: {
                conversationIDs
            }
        };
    }
}

export class FetchConversationWithID extends ApiEndpoint {
    public path = "conversation-with-id";

    public async post(
        request: IApiRequest,
        endpoint: IApiEndpointInfo,
        read: IRead,
        modify: IModify,
        http: IHttp,
        persis: IPersistence
    ): Promise<IApiResponse> {
        const currentUser = request.user

        if(!currentUser){
            return {
                status: 500,
                headers: {
                    "Content-Type": "application/json",
                    "Content-Security-Policy":
                    "default-src 'self' http: https: data: blob: 'unsafe-inline' 'unsafe-eval'",
                },
                content: "No user"
            };
        }

        if(!request.content.conversationId){
            return {
                status: 500,
                headers: {
                    "Content-Type": "application/json",
                    "Content-Security-Policy":
                    "default-src 'self' http: https: data: blob: 'unsafe-inline' 'unsafe-eval'",
                },
                content: "No conv id"
            };
        }

        const conversationData = await getConversationWithID(read, request.content.conversationId)

        if(!conversationData){
            return {
                status: 500,
                headers: {
                    "Content-Type": "application/json",
                    "Content-Security-Policy":
                    "default-src 'self' http: https: data: blob: 'unsafe-inline' 'unsafe-eval'",
                },
                content: "Invalid conv id",
            };
        }

        return {
            status: 200,
            headers: {
                "Content-Type": "application/json",
                "Content-Security-Policy":
                "default-src 'self' http: https: data: blob: 'unsafe-inline' 'unsafe-eval'",
            },
            content: conversationData,
        };
    }
}

import {
    IHttp,
    IModify,
    IPersistence,
    IRead,
    ILogger,
  } from "@rocket.chat/apps-engine/definition/accessors";
  import {
    ISlashCommand,
    SlashCommandContext,
  } from "@rocket.chat/apps-engine/definition/slashcommands";

  import { Block } from "@rocket.chat/ui-kit";

  import {
    ButtonElement,
    PlainText,
    SectionBlock, ActionsBlock
  } from "@rocket.chat/ui-kit";

  import { sendNotification} from "./helpers"

  export class Base implements ISlashCommand {
    public command = "llm";
    public i18nDescription = "";
    public providesPreview = false;
    public i18nParamsExample = "";
    public _logger: ILogger;
    public _appId: string;

    constructor(logger: ILogger, appId: string) {
      this._logger = logger;
      this._appId = appId;
    }

    public async executor(
      context: SlashCommandContext,
      read: IRead,
      modify: IModify,
      http: IHttp,
      persist: IPersistence
    ): Promise<void> {

      const mainSection:SectionBlock = {
        appId: this._appId,

        type:"section",
        text: {
          type: "plain_text",
          text: "Would you like to open prompt editor?"
        },
        accessory: {
          appId: this._appId,
          blockId: "block#create_new_chat",
          actionId: "action#create_new_chat",
          type: "button",
          text: {
            type: "plain_text",
            text: "Yes"
          },
          value: "create_new_chat",
          style: "primary",
          url: "http://localhost:3000/api/apps/public/8d4acc61-d871-46e2-94b5-db161448483c/prompt-editor/chat"
        },
      }

      await sendNotification(context, modify, read, [mainSection])

      return

    }
  }

